  const outerLinkEmitted = lexer.state.linkEmitted;
  const outerInRawBlock = lexer.state.inRawBlock;
  lexer.state.linkEmitted = false;
  lexer.state.inLink = true;
  const token: Tokens.Link | Tokens.Image = {
    type: isImage ? 'image' : 'link',
    raw,
    href,
    title,
    text,
    tokens: lexer.inlineTokens(text),
  };
  lexer.state.inLink = false;
  const nested = lexer.state.linkEmitted;
  // image text is flattened to alt, so links inside it do not count
  lexer.state.linkEmitted = isImage ? outerLinkEmitted : (outerLinkEmitted || !nested);
  if (nested && !isImage) {
    // links may not contain links: let the caller fall through to literal text
    lexer.state.inRawBlock = outerInRawBlock;
    lexer.state.linkEmitted = outerLinkEmitted;
    return;
  }
  return token;
}

